-- Let's check the distinct values for telescope status columns to understand "equipment problems"
SELECT DISTINCT equipstatus FROM telescopes;
SELECT DISTINCT calibrstatus FROM telescopes;
SELECT DISTINCT focusquality FROM telescopes;
SELECT DISTINCT coolsysstatus FROM telescopes;
SELECT DISTINCT powerstatus FROM telescopes;
SELECT DISTINCT datastorstatus FROM telescopes;
SELECT DISTINCT netstatus FROM telescopes;
SELECT DISTINCT procqueuestatus FROM telescopes;

-- Let me check if the query needs to be simpler - maybe just aggregate by observatory rather than per telescope
-- Check total count of telescopes and observatories
SELECT COUNT(*) AS total_telescopes FROM telescopes;
SELECT COUNT(DISTINCT observstation) AS total_observatories FROM telescopes;

-- Check for NULL values in key columns
SELECT COUNT(*) FROM telescopes WHERE pointaccarc IS NULL;
SELECT COUNT(*) FROM observatories WHERE atmostransparency IS NULL OR humidityrate IS NULL OR windspeedms IS NULL OR lunardistdeg IS NULL;
